insert into public.stories (id, kind, status, lang, source_url, source_name, attribution, published_at, content, tags, incomplete) values
  ('real-kozhakhmetova-teacher-to-it', 'documented', 'approved', 'ru', 'https://digitalbusiness.kz/2025-04-30/v-60-let-rabotaet-v-it-v-kazahstane-istoriya-bivshey-uchitelnitsi-iz-zhezkazgana/', 'Digital Business', '{"ru":"Ирина Кожахметова. Пересказ интервью Digital Business (30.04.2025, из цикла о сотрудницах KMF).","kk":"Ирина Кожахметова. Digital Business сұхбатының қысқаша мазмұны (30.04.2025, KMF қызметкерлері туралы циклден).","en":"Irina Kozhakhmetova. A retelling of a Digital Business interview (30 Apr 2025, part of a series about KMF employees)."}'::jsonb, '2025-04-30', '{"title":{"ru":"Из школьного учителя — в тимлиды ИТ после 40","kk":"Мектеп мұғалімінен 40-тан кейін IT тимлидке дейін","en":"From school teacher to IT team lead after 40"},"categories":["from-zero","education-journey"],"ageRange":"35-plus","before":{"ru":"Пять лет она преподавала физику и математику в школе Жезказгана.","kk":"Ол Жезқазғандағы мектепте бес жыл физика мен математикадан сабақ берді.","en":"She taught physics and maths at a school in Zhezkazgan for five years."},"challenges":{"ru":"В 42 года новые проекты в головном офисе банка требовали ИТ-навыков, которых у неё не было. Многие отговаривали, а коллеги вокруг были намного моложе.","kk":"42 жасында банктің бас кеңсесіндегі жаңа жобалар оның бойында жоқ IT дағдыларын талап етті. Көпшілік райынан қайтаруға тырысты, ал айналасындағы әріптестер әлдеқайда жас еді.","en":"At 42, new projects at the bank''s head office needed IT skills she did not have. Many people tried to talk her out of it, and her colleagues were much younger."},"turningPoint":{"ru":"В 30 лет она ушла из школы кассиром в банк. А когда семья переехала в Алматы, осознанно выбрала полностью уйти в ИТ-проекты.","kk":"30 жасында мектептен кетіп, банкке кассир болып орналасты. Отбасы Алматыға көшкенде, IT жобаларына толықтай ауысуды саналы түрде таңдады.","en":"At 30 she left school to work as a bank cashier. When the family moved to Almaty, she deliberately chose to switch fully to IT projects."},"actions":{"ru":"За 12 лет в филиале банка она попробовала почти все операционные роли и участвовала во внедрении банковской системы. Потом внедряла программы по всей стране и девять лет работала бизнес-аналитиком. Училась в основном сама.","kk":"Банк филиалында 12 жыл ішінде ол барлық дерлік операциялық рөлдерді байқап көріп, банк жүйесін енгізуге қатысты. Кейін бүкіл ел бойынша бағдарламалар енгізіп, тоғыз жыл бизнес-талдаушы болып жұмыс істеді. Негізінен өз бетімен үйренді.","en":"Over 12 years at a bank branch she tried almost every operational role and helped roll out a banking system. Later she rolled out software across the country and worked as a business analyst for nine years. She learned mostly on her own."},"now":{"ru":"В 58 лет она стала тимлидом отдела разработки в KMF. В 60 руководит командой из 17 человек.","kk":"58 жасында KMF-те әзірлеу бөлімінің тимлиді болды. 60 жасында 17 адамнан тұратын команданы басқарады.","en":"At 58 she became a development team lead at KMF. At 60 she leads a team of 17 people."},"advice":{"ru":"Её принцип: если чего-то хочешь, просто делай — возможности найдутся. Не бойся пробовать и глубоко вникай в то, чем занимаешься.","kk":"Оның ұстанымы: бір нәрсені қаласаң, жай ғана істей бер — мүмкіндік табылады. Байқап көруден қорықпа және ісіңе терең үңіл.","en":"Her rule: if you want something, just do it and opportunities will come. Don''t be afraid to try, and go deep into what you do."}}'::jsonb, '{"start":["small-town","late-start"],"interests":["tech","science"],"fears":["too-late","judgement"],"education":["university","self-taught"],"challenges":["confidence"],"motives":["curiosity","family"],"decisions":["gradual-change"],"transitions":["late-career-change","relocation"]}'::jsonb, '[]'::jsonb),
  ('real-eseikyzy-finance-to-it', 'documented', 'approved', 'ru', 'https://digitalbusiness.kz/2024-06-10/kak-devushka-iz-taldikorgana-v-31-god-nachala-vse-s-nulya/', 'Digital Business', '{"ru":"Арай Есейқызы. Пересказ интервью Digital Business (11.06.2024).","kk":"Арай Есейқызы. Digital Business сұхбатының қысқаша мазмұны (11.06.2024).","en":"Arai Eseikyzy. A retelling of a Digital Business interview (11 Jun 2024)."}'::jsonb, '2024-06-11', '{"title":{"ru":"Финансовый директор клиники ушла в ИТ после «Болашака»","kk":"Клиниканың қаржы директоры «Болашақтан» кейін IT-ге ауысты","en":"A clinic''s finance director moved into IT after Bolashak"},"categories":["from-zero","study-abroad"],"ageRange":"25-34","before":{"ru":"Она выросла в Талдыкоргане, училась на финансиста в КазНУ и ЕНУ. Начала в новой клинике в Актау с маркетинга и за несколько лет стала финансовым директором.","kk":"Ол Талдықорғанда өсті, ҚазҰУ мен ЕҰУ-да қаржыгерлікке оқыды. Ақтаудағы жаңа клиникада маркетингтен бастап, бірнеше жылда қаржы директоры болды.","en":"She grew up in Taldykorgan and studied finance at KazNU and ENU. She started in marketing at a new clinic in Aktau and within a few years became its finance director."},"challenges":{"ru":"Начинать учёбу в 31 год было некомфортно. При поиске работы в ИТ было много отказов: её считали слишком опытной, а несколько раз отказали, потому что она женщина с детьми.","kk":"31 жасында оқуды бастау ыңғайсыз болды. IT-ден жұмыс іздегенде көп бас тартулар болды: оны тым тәжірибелі деп санады, бірнеше рет балалы әйел болғаны үшін бас тартты.","en":"Starting to study at 31 was uncomfortable. Looking for an IT job she got many rejections: she was seen as overqualified, and several times she was turned down for being a woman with children."},"turningPoint":{"ru":"В декрете она поступила по «Болашаку» в магистратуру по управлению проектами в Уорикском университете (Великобритания). Вернувшись, поняла, что в клинике расти некуда, а ментор помог ей увидеть ИТ с другой стороны.","kk":"Декретте жүріп, «Болашақ» арқылы Уорик университетінде (Ұлыбритания) жобаларды басқару магистратурасына түсті. Оралған соң клиникада өсетін жер жоқ екенін түсінді, ал тәлімгер IT-ді басқа қырынан көруге көмектесті.","en":"While on maternity leave she won a Bolashak place for a master''s in project management at the University of Warwick (UK). Back home she saw there was no room to grow at the clinic, and a mentor helped her see IT differently."},"actions":{"ru":"Она прошла курсы по продакт-менеджменту и SQL. Работу нашла в стартапе грузоперевозок: от отклика до оффера прошло 10 дней, а через три месяца её повысили до операционного директора.","kk":"Ол продакт-менеджмент пен SQL курстарынан өтті. Жүк тасымалы стартапынан жұмыс тапты: өтінімнен офферге дейін 10 күн өтті, ал үш айдан кейін операциялық директор болып көтерілді.","en":"She took courses in product management and SQL. She found a job at a freight startup: ten days from application to offer, and three months later she was promoted to operations director."},"now":{"ru":"Сейчас она проектный менеджер в астанинской компании ROQED, которая делает VR- и AR-тренажёры для производства. Ещё ведёт курсы английского для ИТ-менеджеров.","kk":"Қазір ол өндіріске арналған VR және AR тренажерлерін жасайтын астаналық ROQED компаниясында жоба менеджері. IT менеджерлерге арналған ағылшын тілі курстарын да жүргізеді.","en":"She is now a project manager at ROQED in Astana, which makes VR and AR training simulators for industry. She also runs English courses for IT managers."},"advice":{"ru":"Из её опыта: опыт из другой сферы пригодится, а в новом проекте не стыдно задавать много вопросов, даже если они кажутся глупыми.","kk":"Оның тәжірибесінен: басқа саладағы тәжірибе пайдаға асады, ал жаңа жобада ақымақ болып көрінсе де көп сұрақ қоюдан ұялмау керек.","en":"From her experience: what you learned in another field will help, and in a new project it''s fine to ask lots of questions, even ones that seem silly."}}'::jsonb, '{"start":["small-town"],"interests":["tech","business","languages-culture"],"fears":["too-late","judgement"],"education":["university","abroad-study"],"challenges":["family","time","confidence"],"motives":["curiosity","impact"],"decisions":["mentor","move-abroad","gradual-change"],"transitions":["career-change","relocation"]}'::jsonb, '[]'::jsonb),
  ('real-iskendir-bolashak-village-teacher', 'documented', 'approved', 'ru', 'https://www.inform.kz/ru/bolashakovec-posle-ucheby-za-rubezhom-rabotaet-v-sel-skoy-shkole_a3243096', 'Казинформ', '{"ru":"Абзал Искендир. Пересказ интервью Казинформа (10.05.2018). Требования «Болашака» с тех пор изменились.","kk":"Абзал Искендир. Қазинформ сұхбатының қысқаша мазмұны (10.05.2018). «Болашақ» талаптары содан бері өзгерді.","en":"Abzal Iskendir. A retelling of a Kazinform interview (10 May 2018). Bolashak''s requirements have changed since then."}'::jsonb, '2018-05-10', '{"title":{"ru":"Сельский учитель поехал учиться в Японию — и вернулся в свою школу","kk":"Ауыл мұғалімі Жапонияға оқуға барып, өз мектебіне оралды","en":"A village teacher studied in Japan and came back to his school"},"categories":["study-abroad","education-journey"],"ageRange":"25-34","before":{"ru":"Он вырос в селе в Кызылординской области, окончил физфак в Актобе и с 2006 года преподавал физику в сельской школе. В 2013 году стал «Учителем года» в районе.","kk":"Ол Қызылорда облысындағы ауылда өсті, Ақтөбеде физика факультетін бітіріп, 2006 жылдан бері ауыл мектебінде физикадан сабақ берді. 2013 жылы аудандағы «Жыл мұғалімі» атанды.","en":"He grew up in a village in Kyzylorda region, studied physics in Aktobe and from 2006 taught physics at a village school. In 2013 he was named his district''s Teacher of the Year."},"challenges":{"ru":"Стипендиатом он стал в 28 лет, а на первом тесте IELTS набрал 3,5 балла. Для залога двух домов не хватило, и за него поручились четверо друзей и коллег. Учиться после десяти лет перерыва было тяжело: из лаборатории он уходил за полночь.","kk":"Ол стипендиат болғанда 28 жаста еді, ал алғашқы IELTS тестінен 3,5 балл алды. Кепілге екі үй жетпеді, сондықтан оған төрт досы мен әріптесі кепіл болды. Он жыл үзілістен кейін оқу қиын болды: зертханадан түн ортасынан кейін шығатын.","en":"He won the scholarship at 28 and scored 3.5 on his first IELTS test. Two houses were not enough as collateral, so four friends and colleagues stood guarantee for him. Studying after a ten-year break was hard: he often left the lab after midnight."},"turningPoint":{"ru":"Он захотел получить образование за рубежом и подал документы на «Болашак».","kk":"Ол шетелде білім алғысы келіп, «Болашаққа» құжат тапсырды.","en":"He wanted to study abroad and applied for Bolashak."},"actions":{"ru":"Год учил английский в Норвиче (Великобритания) и поднял IELTS до 6,5. Потом поступил в магистратуру по ядерной физике в Осакском университете и уехал в Японию вместе с семьёй.","kk":"Норвичте (Ұлыбритания) бір жыл ағылшын тілін оқып, IELTS-ті 6,5-ке көтерді. Кейін Осака университетінде ядролық физика магистратурасына түсіп, отбасымен Жапонияға кетті.","en":"He spent a year learning English in Norwich (UK) and raised his IELTS to 6.5. Then he entered a master''s in nuclear physics at Osaka University and moved to Japan with his family."},"now":{"ru":"На момент интервью он снова преподавал в родном районе и не собирался уезжать: успех каждого ученика считает своим достижением.","kk":"Сұхбат кезінде ол туған ауданында қайта сабақ беріп жүрген және кетуді жоспарламаған: әр оқушының табысын өз жетістігі санайды.","en":"At the time of the interview he was teaching in his home district again and did not plan to leave: he sees each student''s success as his own achievement."},"advice":{"ru":"Возраст не помеха, если человек стремится к знаниям.","kk":"Адам білімге ұмтылса, жас кедергі емес.","en":"Age is no obstacle if you want to learn."}}'::jsonb, '{"start":["small-town","late-start"],"interests":["science","education"],"fears":["too-late","money"],"education":["university","abroad-study"],"challenges":["language","money"],"motives":["impact","curiosity"],"decisions":["move-abroad"],"transitions":["relocation"]}'::jsonb, '[]'::jsonb),
  ('real-tleukulov-boxing-to-ai', 'documented', 'approved', 'ru', 'https://digitalbusiness.kz/2026-11-18/iz-boksa-v-it-kak-molodoy-kazahstanets-stroit-kareru-v-kremnievoy-doline/', 'Digital Business', '{"ru":"Ибрагим Тлеукулов. Пересказ интервью Digital Business (18.11.2026).","kk":"Ибрагим Тлеуқұлов. Digital Business сұхбатының қысқаша мазмұны (18.11.2026).","en":"Ibragim Tleukulov. A retelling of a Digital Business interview (18 Nov 2026)."}'::jsonb, '2026-11-18', '{"title":{"ru":"Боксёр после травмы ушёл в программирование и ИИ","kk":"Боксшы жарақаттан кейін бағдарламалау мен ЖИ-ге бет бұрды","en":"After an injury, a boxer turned to programming and AI"},"categories":["unexpected-passion","study-abroad"],"ageRange":"18-24","before":{"ru":"С восьми лет он занимался боксом: больше 200 боёв, молодёжная сборная Казахстана. Параллельно увлекался математикой и программированием и получил грант в Almaty International School.","kk":"Ол сегіз жасынан бокспен айналысты: 200-ден астам жекпе-жек, Қазақстанның жастар құрамасы. Қатар математика мен бағдарламалауға қызығып, Almaty International School-ға грант алды.","en":"He boxed from the age of eight: over 200 fights and Kazakhstan''s youth team. At the same time he loved maths and programming and won a grant to Almaty International School."},"challenges":{"ru":"Из-за травмы пришлось оставить бокс, который был главной целью. Было тяжело: вне спорта его воспринимали только как боксёра.","kk":"Жарақатқа байланысты басты мақсаты болған бокстан бас тартуға тура келді. Қиын болды: спорттан тыс жерде оны тек боксшы ретінде қабылдады.","en":"An injury forced him to give up boxing, which had been his main goal. It was hard: outside sport people saw him only as a boxer."},"turningPoint":{"ru":"Он изучил, какие отрасли растут быстрее всего, и вернулся к программированию как раз тогда, когда появился ChatGPT.","kk":"Ол қай салалар ең жылдам өсіп жатқанын зерттеп, ChatGPT пайда болған кезде бағдарламалауға қайта оралды.","en":"He looked at which industries were growing fastest and went back to programming just as ChatGPT appeared."},"actions":{"ru":"Четыре месяца готовился к SAT, сдал IELTS на 8.0 и поступил на Computer Science в американский DePauw University с полной оплатой обучения. Начал вести блог об ИИ-инструментах и за три месяца вырос с 600 до 10 тысяч подписчиков.","kk":"Төрт ай SAT-қа дайындалып, IELTS-ті 8.0-ге тапсырды және оқу ақысы толық төленетін америкалық DePauw University-дің Computer Science мамандығына түсті. ЖИ құралдары туралы блог жүргізіп, үш айда 600-ден 10 мың жазылушыға жетті.","en":"He prepared for the SAT for four months, scored 8.0 on IELTS and entered Computer Science at DePauw University in the US on a full-tuition scholarship. He started a blog about AI tools and grew from 600 to 10,000 followers in three months."},"now":{"ru":"Летом он стал первым сотрудником ИИ-стартапа Lamina Labs из Сан-Франциско и отвечал за вывод продукта к людям. Учёбу продолжает.","kk":"Жазда ол Сан-Францискодағы Lamina Labs ЖИ-стартапының алғашқы қызметкері болып, өнімді нарыққа шығаруға жауап берді. Оқуын жалғастыруда.","en":"Over the summer he became the first employee of Lamina Labs, an AI startup in San Francisco, responsible for getting the product to users. He is continuing his studies."}}'::jsonb, '{"start":["big-city"],"interests":["sport","tech","business"],"fears":["unknown-future"],"education":["university","abroad-study"],"challenges":["confidence"],"motives":["curiosity","recognition"],"decisions":["move-abroad","side-project"],"transitions":["career-change","school-to-university"]}'::jsonb, '["advice"]'::jsonb),
  ('real-narushev-orientalist-to-music', 'documented', 'approved', 'ru', 'https://the-steppe.com/razvlecheniya/creativesteppe-ya-hochu-chtoby-pod-kazahskie-narodnye-instrumenty-mozhno-bylo-zatusit-muzykant-rasskazal-o-kazahstanskom-trepe', 'The Steppe', '{"ru":"Жалгас Нарушев. Пересказ интервью The Steppe (24.06.2022).","kk":"Жалғас Нарушев. The Steppe сұхбатының қысқаша мазмұны (24.06.2022).","en":"Zhalgas Narushev. A retelling of a The Steppe interview (24 Jun 2022)."}'::jsonb, '2022-06-24', '{"title":{"ru":"Бросил востоковедение ради музыки — и выкупил студию","kk":"Шығыстануды музыка үшін тастап, студияны сатып алды","en":"Dropped Oriental studies for music and bought the studio"},"categories":["changed-major","unexpected-passion"],"before":{"ru":"Он из Уральска, в детстве окончил музыкальную школу: домбра, шанкобыз, духовые. Потом поступил в Алматы на востоковеда-арабиста.","kk":"Ол Оралдан, бала кезінде музыка мектебін бітірді: домбыра, шаңқобыз, үрмелі аспаптар. Кейін Алматыда шығыстанушы-арабист мамандығына түсті.","en":"He is from Oral (Uralsk) and finished music school as a child: dombra, shankobyz and wind instruments. Then he went to Almaty to study Oriental and Arabic studies."},"challenges":{"ru":"Родители сначала были против, когда он ушёл из университета. В семье он единственный, кто занимается музыкой.","kk":"Ол университеттен кеткенде ата-анасы алғашында қарсы болды. Отбасында музыкамен айналысатын жалғыз өзі.","en":"His parents were against it at first when he left university. He is the only one in his family who does music."},"turningPoint":{"ru":"Во время учёбы он вернулся к музыке, а на третьем курсе бросил университет.","kk":"Оқу кезінде музыкаға қайта оралып, үшінші курста университетті тастады.","en":"While at university he came back to music, and in his third year he dropped out."},"actions":{"ru":"Он стал битмейкером в музыкальной студии в Алматы, а позже выкупил её. Выпускает свои треки и работает над трилогией альбомов.","kk":"Ол Алматыдағы музыка студиясында битмейкер болып, кейін оны сатып алды. Өз тректерін шығарып, альбомдар трилогиясымен жұмыс істеп жатыр.","en":"He became a beatmaker at a music studio in Almaty and later bought it. He releases his own tracks and is working on an album trilogy."},"now":{"ru":"Со временем семья стала его поддерживать. Его цель — поставить Центральную Азию на мировую карту хип-хопа.","kk":"Уақыт өте келе отбасы оны қолдай бастады. Оның мақсаты — Орталық Азияны хип-хоптың әлемдік картасына шығару.","en":"Over time his family came to support him. His goal is to put Central Asia on the world map of hip-hop."}}'::jsonb, '{"start":["family-pressure"],"interests":["creative","languages-culture"],"fears":["disappointing-parents"],"education":["university","dropped-out"],"challenges":["family"],"motives":["freedom","recognition"],"decisions":["side-project"],"transitions":["side-to-main","relocation"]}'::jsonb, '["advice"]'::jsonb),
  ('real-erkenes-it-to-farming', 'documented', 'approved', 'ru', 'https://digitalbusiness.kz/2026-02-24/kazahstanets-uchilsya-na-aytishnika-no-stal-myasnikom/', 'Digital Business', '{"ru":"Айдын Еркенес. Пересказ интервью Digital Business (24.02.2026).","kk":"Айдын Еркенес. Digital Business сұхбатының қысқаша мазмұны (24.02.2026).","en":"Aidyn Erkenes. A retelling of a Digital Business interview (24 Feb 2026)."}'::jsonb, '2026-02-24', '{"title":{"ru":"Учился на айтишника, а нашёл себя в семейном фермерском деле","kk":"IT мамандығына оқыды, бірақ өзін отбасылық фермерлік істен тапты","en":"Studied IT, but found his calling in the family farm business"},"categories":["first-business","unexpected-passion"],"before":{"ru":"Он вырос в селе в Жамбылской области. Отец разводил скот и продавал мясо, сын помогал, но продолжать дело не собирался: хотел стать программистом и учился в Astana IT University.","kk":"Ол Жамбыл облысындағы ауылда өсті. Әкесі мал өсіріп, ет сататын, ұлы көмектесетін, бірақ істі жалғастыруды ойламаған: бағдарламашы болғысы келіп, Astana IT University-де оқыды.","en":"He grew up in a village in Zhambyl region. His father raised livestock and sold meat; he helped but did not plan to continue the business. He wanted to be a programmer and studied at Astana IT University."},"challenges":{"ru":"Работа за компьютером не давала ему ощущения реального результата. Окружающие реагировали по-разному: кто-то не понимал его выбора.","kk":"Компьютер алдындағы жұмыс оған нақты нәтиже сезімін бермеді. Айналасындағылар әртүрлі қабылдады: кейбірі оның таңдауын түсінбеді.","en":"Computer work never gave him a sense of real results. People reacted differently: some did not understand his choice."},"turningPoint":{"ru":"Он попробовал фриланс и работу в компании и понял, что это не его. Решил развивать семейное дело.","kk":"Ол фриланс пен компаниядағы жұмысты байқап көріп, бұл өзінікі емес екенін түсінді. Отбасылық істі дамытуды шешті.","en":"He tried freelancing and a company job and realised it was not for him. He decided to grow the family business."},"actions":{"ru":"Он перенёс в хозяйство то, чему научился в ИТ: учёт, понятная схема продаж, работа напрямую с покупателями и соцсети. Сам участвует во всех этапах, рабочий день начинается в 5 утра.","kk":"Ол IT-де үйренгенін шаруашылыққа енгізді: есеп, түсінікті сату жүйесі, сатып алушылармен тікелей жұмыс және әлеуметтік желілер. Барлық кезеңге өзі қатысады, жұмыс күні таңғы 5-те басталады.","en":"He brought what he learned in IT to the farm: bookkeeping, a clear sales model, selling directly to customers, and social media. He takes part in every stage himself, and his day starts at 5 a.m."},"now":{"ru":"У хозяйства больше 200 голов скота, свой магазин и несколько сотен постоянных клиентов. Он говорит, что нашёл себя.","kk":"Шаруашылықта 200-ден астам мал, өз дүкені және бірнеше жүз тұрақты клиент бар. Ол өзін тапқанын айтады.","en":"The farm has over 200 head of cattle, its own shop and several hundred regular customers. He says he has found his place."},"advice":{"ru":"Такое дело может приносить доход, но это не лёгкие деньги: нужно много трудиться и не экономить на качестве.","kk":"Мұндай іс табыс әкелуі мүмкін, бірақ бұл оңай ақша емес: көп еңбек ету және сападан үнемдемеу керек.","en":"A business like this can pay, but it is not easy money: you have to work hard and never cut corners on quality."}}'::jsonb, '{"start":["small-town"],"interests":["business","tech","nature"],"fears":["judgement"],"education":["university"],"challenges":["time"],"motives":["family","impact"],"decisions":["experiments"],"transitions":["university-to-work","career-change"]}'::jsonb, '[]'::jsonb),
  ('real-duisekhan-full-grant-nyu-abu-dhabi', 'documented', 'approved', 'ru', 'https://the-steppe.com/steppe-youth/polnyj-grant-v-nyu-abu-dhabi-istorija-postuplenija-shkolnicy-iz-kazahstana', 'The Steppe', '{"ru":"Дүйсехан Талшын. Пересказ материала The Steppe (30.05.2026).","kk":"Дүйсехан Талшын. The Steppe материалының қысқаша мазмұны (30.05.2026).","en":"Duisekhan Talshyn. A retelling of a The Steppe article (30 May 2026)."}'::jsonb, '2026-05-30', '{"title":{"ru":"Школьница без денег на учёбу получила полный грант в NYU Abu Dhabi","kk":"Оқуға ақшасы жоқ оқушы қыз NYU Abu Dhabi-ге толық грант алды","en":"A schoolgirl who couldn''t pay for study won a full grant to NYU Abu Dhabi"},"categories":["study-abroad","education-journey"],"ageRange":"under-18","before":{"ru":"Она школьница из Казахстана и хотела учиться за рубежом. В отличие от многих одноклассников, платить за обучение её семья не могла, поэтому шансом был только полный грант.","kk":"Ол Қазақстандағы оқушы және шетелде оқығысы келді. Көптеген сыныптастарынан айырмашылығы, отбасы оқу ақысын төлей алмайтын, сондықтан жалғыз мүмкіндік — толық грант еді.","en":"She is a school student from Kazakhstan who wanted to study abroad. Unlike many classmates, her family could not pay tuition, so a full grant was her only chance."},"challenges":{"ru":"Давление изнутри, постоянное сравнение с другими, страх быть недостаточно хорошей и неясное будущее. Бывали моменты, когда хотелось всё бросить, а страх перед экзаменами доводил до слёз.","kk":"Іштей қысым, өзгелермен үнемі салыстыру, жеткілікті жақсы болмаудан қорқу және белгісіз болашақ. Бәрін тастағысы келген сәттер болды, ал емтихан қорқынышы көз жасына дейін жеткізді.","en":"Inner pressure, constant comparison with others, fear of not being good enough and an uncertain future. At times she wanted to quit, and exam stress brought her to tears."},"turningPoint":{"ru":"Она стала финалисткой менторской программы Luminary Education и получила поддержку менторов, мамы и друзей, которые проходили тот же путь.","kk":"Ол Luminary Education тәлімгерлік бағдарламасының финалисі болып, тәлімгерлердің, анасының және сол жолдан өткен достарының қолдауын алды.","en":"She became a finalist of the Luminary Education mentoring programme and got support from mentors, her mother and friends going through the same process."},"actions":{"ru":"Готовилась к SAT, писала эссе, занималась английским и своими проектами. Летом попросила родителей купить доску и расписывала на ней задачи по часам, каждый день занимаясь хотя бы одной частью поступления.","kk":"SAT-қа дайындалып, эссе жазды, ағылшын тілімен және өз жобаларымен айналысты. Жазда ата-анасынан тақта сатып алуды сұрап, тапсырмаларды сағатпен жоспарлады, күн сайын түсудің кем дегенде бір бөлігімен айналысты.","en":"She prepared for the SAT, wrote essays, worked on her English and her own projects. Over the summer she asked her parents for a whiteboard and planned tasks hour by hour, working on at least one part of the application every day."},"now":{"ru":"Она получила полный грант в NYU Abu Dhabi и готовится к учёбе.","kk":"Ол NYU Abu Dhabi-ге толық грант алып, оқуға дайындалып жатыр.","en":"She won a full grant to NYU Abu Dhabi and is getting ready to start."},"advice":{"ru":"Работай над тайм-менеджментом и систематичностью. Эссе показывает, как ты понимаешь свою жизнь и ценности, а активности — чем ты живёшь.","kk":"Уақытты басқару мен жүйелілікке жұмыс істе. Эссе өз өміріңді және құндылықтарыңды қалай түсінетініңді, ал белсенділіктер немен өмір сүретініңді көрсетеді.","en":"Work on time management and consistency. The essay shows how you understand your life and values; your activities show what you live for."}}'::jsonb, '{"start":["low-income"],"interests":["education","languages-culture"],"fears":["not-talented-enough","failure","money"],"education":["school","abroad-study"],"challenges":["money","confidence"],"motives":["curiosity","freedom"],"decisions":["mentor","move-abroad"],"transitions":["school-to-university","relocation"]}'::jsonb, '[]'::jsonb),
  ('real-sembay-energy-to-teacher', 'documented', 'approved', 'ru', 'https://www.inform.kz/ru/pochemu-energetik-reshil-stat-uchitelem-istoriya-uchastnika-teach-for-qazaqstan-341f0970', 'Казинформ', '{"ru":"Серик Сембай. Пересказ интервью Казинформа (29.09.2026) об участнике программы Teach for Qazaqstan.","kk":"Серік Сембай. Қазинформның Teach for Qazaqstan бағдарламасы қатысушысы туралы сұхбатының қысқаша мазмұны (29.09.2026).","en":"Serik Sembay. A retelling of a Kazinform interview (29 Sep 2026) with a Teach for Qazaqstan participant."}'::jsonb, '2026-09-29', '{"title":{"ru":"Энергетик с горнорудного предприятия стал учителем математики","kk":"Кен өндіру кәсіпорнының энергетигі математика мұғалімі болды","en":"An energy engineer from a mining company became a maths teacher"},"categories":["from-zero","unexpected-passion"],"before":{"ru":"Он работал энергетиком на горнорудном предприятии. О программе Teach for Qazaqstan узнал из подкаста, и с тех пор его время от времени тянуло попробовать себя в образовании.","kk":"Ол кен өндіру кәсіпорнында энергетик болып жұмыс істеді. Teach for Qazaqstan бағдарламасы туралы подкасттан білді, содан бері білім саласында өзін сынап көргісі келе берді.","en":"He worked as an energy engineer at a mining company. He heard about Teach for Qazaqstan on a podcast, and from then on he kept thinking about trying education."},"challenges":{"ru":"Решиться он не мог два года: мысли о смене профессии то появлялись, то уходили. В школе сложнее всего оказались переезд, большая ответственность и много бумажной работы.","kk":"Ол екі жыл бойы шешім қабылдай алмады: мамандықты ауыстыру ойы келіп-кетіп жүрді. Мектепте ең қиыны көшу, үлкен жауапкершілік және қағаз жұмысының көптігі болды.","en":"He could not decide for two years: the thought of changing careers kept coming and going. At school the hardest parts were moving, the big responsibility and lots of paperwork."},"turningPoint":{"ru":"Его зацепило, что даже маленькие изменения в школе влияют на детей и людей вокруг них. Изучив ценности программы, он подал заявку.","kk":"Мектептегі кішкентай өзгерістердің өзі балаларға және олардың айналасындағы адамдарға әсер ететіні оны қызықтырды. Бағдарлама құндылықтарымен танысып, өтінім берді.","en":"What hooked him was that even small changes at school affect children and the people around them. After studying the programme''s values, he applied."},"actions":{"ru":"Прошёл все этапы отбора, переподготовку и летнюю практику в лагере для школьников. Теперь преподаёт математику в региональной школе по двухлетней программе с обучением и наставничеством.","kk":"Іріктеудің барлық кезеңінен, қайта даярлаудан және оқушыларға арналған жазғы лагерьдегі тәжірибеден өтті. Енді оқыту мен тәлімгерлігі бар екі жылдық бағдарлама бойынша өңірлік мектепте математикадан сабақ береді.","en":"He passed every selection stage, retraining and a summer practice at a camp for pupils. Now he teaches maths at a regional school in a two-year programme with training and mentoring."},"now":{"ru":"Он говорит, что ни о чём не жалеет, а работа с детьми даёт ему веру в будущее.","kk":"Ол ештеңеге өкінбейтінін, ал балалармен жұмыс оған болашаққа сенім беретінін айтады.","en":"He says he has no regrets, and working with children gives him faith in the future."},"advice":{"ru":"Если путь действительно отзывается и ты хочешь попробовать — не сомневайся.","kk":"Егер бұл жол шынымен жүрегіңе жақын болса және байқап көргің келсе — күмәнданба.","en":"If the path truly speaks to you and you want to try it, don''t hold back."}}'::jsonb, '{"start":["late-start"],"interests":["education","people","science"],"fears":["wrong-choice","unknown-future"],"education":["university"],"challenges":["time","confidence"],"motives":["impact","belonging"],"decisions":["gradual-change"],"transitions":["career-change","relocation"]}'::jsonb, '[]'::jsonb),
  ('real-sultankulov-prosecutor-to-developer', 'documented', 'approved', 'ru', 'https://digitalbusiness.kz/2025-06-17/istoriya-kazahstantsa-kotoriy-ne-poboyalsya-v-38-let-kardinalno-izmenit-zhizn/', 'Digital Business', '{"ru":"Бауыржан Султанкулов. Пересказ материала Digital Business (17.06.2025).","kk":"Бауыржан Сұлтанқұлов. Digital Business материалының қысқаша мазмұны (17.06.2025).","en":"Baurzhan Sultankulov. A retelling of a Digital Business article (17 Jun 2025)."}'::jsonb, '2025-06-17', '{"title":{"ru":"Был прокурором и аудитором, а в 38 стал разработчиком","kk":"Прокурор және аудитор болды, ал 38 жасында әзірлеуші атанды","en":"A former prosecutor and auditor became a developer at 38"},"categories":["other-than-parents","from-zero"],"ageRange":"35-plus","before":{"ru":"Он из Тараза. Специальность за него выбрали родители — иностранные языки. Преподавать не получилось из-за очень низкой зарплаты, продажи тоже оказались не его. Потом были семь лет в прокуратуре, MBA и работа в аудите.","kk":"Ол Тараздан. Мамандықты оның орнына ата-анасы таңдады — шет тілдері. Жалақы өте төмен болғандықтан сабақ беру мүмкін болмады, сауда да оныкі емес болып шықты. Кейін прокуратурада жеті жыл, MBA және аудиторлық жұмыс болды.","en":"He is from Taraz. His parents chose his major for him: foreign languages. Teaching didn''t work out because the pay was very low, and sales wasn''t for him either. Then came seven years at the prosecutor''s office, an MBA and work in audit."},"challenges":{"ru":"Чтобы учиться программированию, он ушёл с работы и жил с семьёй на накопления. Родные и друзья не понимали, зачем начинать с нуля. На одном собеседовании он услышал, как его назвали «30-летним джуном».","kk":"Бағдарламалауды үйрену үшін жұмыстан кетіп, отбасымен жинаған ақшаға өмір сүрді. Туыстары мен достары нөлден бастаудың не керегі барын түсінбеді. Бір сұхбатта өзін «30 жастағы джун» деп атағанын естіді.","en":"To study programming he quit his job and lived with his family on savings. Relatives and friends didn''t understand why he was starting from zero. At one interview he overheard himself called a “30-year-old junior”."},"turningPoint":{"ru":"Ему стало интересно, как создаются цифровые продукты. Он прочитал пару книг, посмотрел видео и в 2018 году записался на курсы программирования.","kk":"Цифрлық өнімдердің қалай жасалатыны оған қызық болды. Бірнеше кітап оқып, бейне көріп, 2018 жылы бағдарламалау курстарына жазылды.","en":"He became curious about how digital products are made. He read a couple of books, watched videos and in 2018 signed up for programming courses."},"actions":{"ru":"Через два года учёбы прошёл 5–6 собеседований и в 38 лет попал на стажировку, где полгода работал бесплатно ради реального опыта. Потом работал в международной команде.","kk":"Екі жыл оқығаннан кейін 5–6 сұхбаттан өтіп, 38 жасында тағылымдамаға түсті, онда нақты тәжірибе үшін жарты жыл тегін жұмыс істеді. Кейін халықаралық командада жұмыс істеді.","en":"After two years of study he went through 5–6 interviews and at 38 got an internship, where he worked unpaid for six months to gain real experience. Later he worked in an international team."},"now":{"ru":"За четыре года он сменил пять компаний и сейчас работает разработчиком в банке. В команде в основном молодые ребята, и общий язык он нашёл со всеми.","kk":"Төрт жылда бес компания ауыстырып, қазір банкте әзірлеуші болып жұмыс істейді. Командада негізінен жастар, ол бәрімен тіл табысты.","en":"In four years he changed five companies and now works as a developer at a bank. His team is mostly young, and he gets along with everyone."}}'::jsonb, '{"start":["family-pressure","late-start"],"interests":["tech","business"],"fears":["too-late","judgement","money"],"education":["university","self-taught"],"challenges":["money","family"],"motives":["curiosity","freedom"],"decisions":["gradual-change"],"transitions":["late-career-change","career-change"]}'::jsonb, '["advice"]'::jsonb),
  ('real-aimagambetov-gap-year-grant', 'documented', 'approved', 'ru', 'https://tengrinews.kz/profitably/delat-ne-postupil-grant-oplachivat-vuz-deneg-506865/', 'Tengrinews', '{"ru":"Асхат Аймагамбетов. Пересказ его слов по материалу Tengrinews (07.08.2023); Informburo (03.08.2024) называет его экс-министром образования и депутатом парламента. Правила пересдачи ЕНТ с тех пор могли измениться — уточняйте у приёмной комиссии.","kk":"Асхат Аймағамбетов. Tengrinews материалы бойынша оның сөздерінің қысқаша мазмұны (07.08.2023); Informburo (03.08.2024) оны білім беру ісінің бұрынғы министрі және парламент депутаты деп атайды. ҰБТ-ны қайта тапсыру ережелері содан бері өзгеруі мүмкін — қабылдау комиссиясынан нақтылаңыз.","en":"Askhat Aimagambetov. A retelling of his words from a Tengrinews article (7 Aug 2023); Informburo (3 Aug 2024) calls him a former education minister and member of parliament. The rules for retaking the UNT may have changed since — check with the admissions office."}'::jsonb, '2023-08-07', '{"title":{"ru":"Не прошёл на грант после школы — взял год и выиграл его","kk":"Мектептен кейін грантқа өтпеді — бір жыл дайындалып, оны жеңіп алды","en":"Missed a grant after school, took a year and won one"},"categories":["failed-restart","education-journey"],"before":{"ru":"После окончания школы он не смог сразу поступить в университет на грант.","kk":"Мектепті бітірген соң ол бірден университетке грантпен түсе алмады.","en":"After finishing school he could not get a university grant straight away."},"challenges":{"ru":"Пришлось выбирать: идти на платное отделение или взять паузу на год, чтобы лучше подготовиться.","kk":"Таңдау керек болды: ақылы бөлімге бару немесе жақсы дайындалу үшін бір жыл үзіліс алу.","en":"He had to choose: study on a paid place or take a year off to prepare better."},"turningPoint":{"ru":"Он взял ответственность на себя и решил поступать через год.","kk":"Ол жауапкершілікті өзіне алып, бір жылдан кейін түсуді шешті.","en":"He took responsibility and decided to apply again a year later."},"actions":{"ru":"Этот год он посвятил упорной подготовке и работе.","kk":"Сол жылды ол табанды дайындық пен жұмысқа арнады.","en":"He spent that year preparing hard and working."},"now":{"ru":"На следующий год он выиграл грант. Позже стал министром образования Казахстана и в 2020 году рассказал эту историю выпускникам, чтобы они не боялись такой паузы.","kk":"Келесі жылы ол грант жеңіп алды. Кейін Қазақстанның білім министрі болды және 2020 жылы түлектер мұндай үзілістен қорықпасын деп осы оқиғаны айтып берді.","en":"The next year he won a grant. He later became Kazakhstan''s education minister and in 2020 told this story to school leavers so they would not fear such a break."},"advice":{"ru":"Если не получил грант, можно взять год, подготовиться, снова сдать ЕНТ и попробовать ещё раз — он сам так сделал.","kk":"Грант алмасаң, бір жыл алып, дайындалып, ҰБТ-ны қайта тапсырып, тағы байқап көруге болады — ол өзі солай істеген.","en":"If you miss a grant, you can take a year, prepare, retake the UNT and try again — he did exactly that."}}'::jsonb, '{"start":[],"interests":[],"fears":[],"education":["school","university"],"challenges":["money"],"motives":[],"decisions":["take-a-break"],"transitions":["gap-year","school-to-university"]}'::jsonb, '[]'::jsonb),
  ('real-mukhamedzhan-army-to-it-grant', 'documented', 'approved', 'ru', 'https://tengrinews.kz/kazakhstan_news/ushl-armiyu-vernulsya-grantom-kazahstanets-postupil-vuz-ent-611519/', 'Tengrinews', '{"ru":"Али Мухамеджан. Пересказ материала Tengrinews (23.10.2026). Условия военных грантов уточняйте в официальных источниках.","kk":"Әли Мұхамеджан. Tengrinews материалының қысқаша мазмұны (23.10.2026). Әскери гранттардың шарттарын ресми дереккөздерден нақтылаңыз.","en":"Ali Mukhamedzhan. A retelling of a Tengrinews article (23 Oct 2026). Check the terms of military grants in official sources."}'::jsonb, '2026-10-23', '{"title":{"ru":"После армии получил грант без ЕНТ и учится на айтишника","kk":"Әскерден кейін ҰБТ-сыз грант алып, IT мамандығына оқып жүр","en":"Won a grant without the UNT after the army and studies IT"},"categories":["education-journey"],"before":{"ru":"В 2022 году он проходил срочную службу в части ПВО недалеко от Астаны и не думал, что служба приведёт его в университет.","kk":"2022 жылы ол Астана маңындағы әуе шабуылына қарсы қорғаныс бөлімінде мерзімді қызмет өтеді және бұл қызмет оны университетке алып келеді деп ойламаған.","en":"In 2022 he was doing military service in an air-defence unit near Astana and never expected it to lead him to university."},"challenges":{"ru":"Грант не дают просто за отслуженный год: при отборе смотрят на дисциплину, результаты подготовки, отношение к службе и рекомендацию командира.","kk":"Грант жай ғана өтелген бір жыл үшін берілмейді: іріктеуде тәртіпке, дайындық нәтижелеріне, қызметке көзқарасқа және командирдің ұсынымына қарайды.","en":"The grant isn''t given just for a year served: selection looks at discipline, training results, attitude to service and the commander''s recommendation."},"turningPoint":{"ru":"Незадолго до увольнения в запас он узнал, что солдаты с хорошими результатами службы могут получить государственный грант на учёбу — без баллов ЕНТ.","kk":"Запасқа шығар алдында ол қызмет нәтижесі жақсы сарбаздар ҰБТ балынсыз мемлекеттік білім грантын ала алатынын білді.","en":"Shortly before discharge he learned that soldiers with good service records can get a state study grant without UNT scores."},"actions":{"ru":"Он прошёл отбор и поступил на факультет информационных технологий ЕНУ имени Гумилёва. Грант покрывает обучение, есть стипендия и приоритет на место в общежитии.","kk":"Ол іріктеуден өтіп, Гумилев атындағы ЕҰУ-дың ақпараттық технологиялар факультетіне түсті. Грант оқу ақысын жабады, стипендия және жатақханадан орын алуға басымдық бар.","en":"He passed the selection and entered the IT faculty of L.N. Gumilyov Eurasian National University. The grant covers tuition, with a stipend and priority for a dorm place."},"now":{"ru":"На момент публикации он учился на четвёртом курсе: программирование, базы данных и разработка информационных систем. Диплом планирует получить в 2027 году.","kk":"Жарияланым кезінде ол төртінші курста оқыған: бағдарламалау, деректер базасы және ақпараттық жүйелерді әзірлеу. Дипломды 2027 жылы алуды жоспарлап отыр.","en":"At the time of publication he was in his fourth year, studying programming, databases and information systems development. He plans to graduate in 2027."},"advice":{"ru":"Тем, кто сейчас служит, — проявлять себя с первых дней: грант дают по итогам отбора, а не за отслуженный год.","kk":"Қазір қызмет етіп жүргендерге — алғашқы күннен өзін көрсету: грант өтелген жыл үшін емес, іріктеу нәтижесі бойынша беріледі.","en":"For those serving now: show yourself from day one — the grant goes by selection results, not for the year served."}}'::jsonb, '{"start":["late-start"],"interests":["tech"],"fears":[],"education":["university"],"challenges":[],"motives":[],"decisions":["take-a-break"],"transitions":["gap-year","school-to-university"]}'::jsonb, '[]'::jsonb),
  ('real-sadvokasova-pilot-cadet', 'documented', 'approved', 'ru', 'https://manshuq.com/articles/career-vzyat-svoyu-vysotu-kak-kazakhstanka-voploshaet-mechtu-stat-pilotessoi-08-2025', 'Manshuq', '{"ru":"Алима Садвокасова. Пересказ материала Manshuq (28.08.2025). Условия программы Air Astana Ab-initio уточняйте на официальном сайте.","kk":"Әлима Садуақасова. Manshuq материалының қысқаша мазмұны (28.08.2025). Air Astana Ab-initio бағдарламасының шарттарын ресми сайттан нақтылаңыз.","en":"Alima Sadvokasova. A retelling of a Manshuq article (28 Aug 2025). Check the Air Astana Ab-initio programme terms on the official site."}'::jsonb, '2025-08-28', '{"title":{"ru":"Легкоатлетка из Павлодара учится на пилота","kk":"Павлодарлық жеңіл атлет қыз ұшқыштыққа оқып жүр","en":"A track athlete from Pavlodar is training to be a pilot"},"categories":["education-journey","study-abroad"],"before":{"ru":"Она выросла в Павлодаре, окончила школу с отличием и занималась лёгкой атлетикой: бег на 400 метров, второй взрослый разряд. О профессии пилота знала только то, что она существует.","kk":"Ол Павлодарда өсті, мектепті үздік бітіріп, жеңіл атлетикамен айналысты: 400 метрге жүгіру, екінші ересек разряд. Ұшқыш мамандығы туралы тек оның бар екенін білетін.","en":"She grew up in Pavlodar, finished school with honours and ran track: the 400 metres, at an adult second-class level. About being a pilot she knew only that the job existed."},"challenges":{"ru":"Отбор шёл в несколько этапов: тесты на анализ информации, тест по физике, математике, логике и памяти, тренажёр Boeing 737, групповые задания и интервью. Она волновалась, а сама учёба оказалась непростой.","kk":"Іріктеу бірнеше кезеңнен тұрды: ақпаратты талдау тесттері, физика, математика, логика және есте сақтау тесті, Boeing 737 тренажері, топтық тапсырмалар және сұхбат. Ол толқыды, ал оқудың өзі оңай болмады.","en":"Selection had several stages: information-analysis tests, a physics, maths, logic and memory test, a Boeing 737 simulator, group tasks and an interview. She was nervous, and the training itself is hard."},"turningPoint":{"ru":"К девятому классу интерес к авиации стал таким сильным, что она решила связать с ней жизнь.","kk":"Тоғызыншы сыныпқа қарай авиацияға қызығушылығы соншалық күшейіп, өмірін онымен байланыстыруды шешті.","en":"By ninth grade her interest in aviation had grown so strong that she decided to build her life around it."},"actions":{"ru":"Она подала заявку в программу подготовки пилотов Air Astana Ab-initio, где не нужно высшее образование, и прошла отбор. По данным материала, обучение оплачивает авиакомпания, но 75% стоимости нужно вернуть за 15 лет работы в ней.","kk":"Ол жоғары білім талап етілмейтін Air Astana Ab-initio ұшқыштар даярлау бағдарламасына өтінім беріп, іріктеуден өтті. Материал бойынша оқуды авиакомпания төлейді, бірақ құнының 75%-ын онда 15 жыл жұмыс істеп өтеу керек.","en":"She applied to Air Astana''s Ab-initio pilot programme, which needs no university degree, and passed the selection. According to the article, the airline pays for training, but 75% of the cost must be repaid over 15 years of work there."},"now":{"ru":"Она учится в лётной школе FTE Jerez в Испании: 13 предметов, включая аэродинамику, метеорологию и навигацию. После обучения кадеты работают в Air Astana.","kk":"Ол Испаниядағы FTE Jerez ұшқыштар мектебінде оқиды: аэродинамика, метеорология және навигацияны қоса алғанда 13 пән. Оқудан кейін кадеттер Air Astana-да жұмыс істейді.","en":"She studies at the FTE Jerez flight school in Spain: 13 subjects, including aerodynamics, meteorology and navigation. After training, cadets work at Air Astana."},"advice":{"ru":"Не бояться и не сомневаться в себе: пробовать и верить в свои силы.","kk":"Қорықпау және өзіңе күмәнданбау: байқап көріп, өз күшіңе сену.","en":"Don''t be afraid or doubt yourself: try, and believe in your own strength."}}'::jsonb, '{"start":[],"interests":["science","sport"],"fears":[],"education":["school","abroad-study"],"challenges":["confidence"],"motives":["curiosity"],"decisions":["move-abroad"],"transitions":["school-to-university","relocation"]}'::jsonb, '[]'::jsonb),
  ('real-nechaev-eco-fairy-tales', 'documented', 'approved', 'ru', 'https://digitalbusiness.kz/2025-08-26/kazahstanets-v-11-let-osnoval-startap-dlya-spaseniya-prirodi-istoriya-shkolnika-iz-karagandi/', 'Digital Business', '{"ru":"Платон Нечаев. Пересказ интервью Digital Business (26.08.2025).","kk":"Платон Нечаев. Digital Business сұхбатының қысқаша мазмұны (26.08.2025).","en":"Platon Nechaev. A retelling of a Digital Business interview (26 Aug 2025)."}'::jsonb, '2025-08-26', '{"title":{"ru":"11-летний школьник превратил свои сказки в экопроект","kk":"11 жасар оқушы өз ертегілерін экожобаға айналдырды","en":"An 11-year-old turned his fairy tales into an eco project"},"categories":["first-business","unexpected-passion"],"ageRange":"under-18","before":{"ru":"Он школьник из Караганды. Первую книжку-сказку с иллюстрациями придумал после конкурса рисунков — про Аппака Байжанова, который нашёл уголь в Караганде.","kk":"Ол Қарағандыдағы оқушы. Алғашқы суретті ертегі кітабын сурет байқауынан кейін ойлап тапты — Қарағандыдан көмір тапқан Аппақ Байжанов туралы.","en":"He is a schoolboy from Karaganda. He came up with his first illustrated fairy-tale book after a drawing contest — about Appak Baizhanov, who found coal in Karaganda."},"challenges":{"ru":"Ему часто говорили, что он делает «не то». Он побеждал не на всех конкурсах, получал отказы, а на встречах с чиновниками слышал «ақша жоқ» — денег нет.","kk":"Оған жиі «дұрыс емес нәрсе істеп жүрсің» деді. Ол барлық байқауда жеңген жоқ, бас тартулар естіді, ал шенеуніктермен кездесулерде «ақша жоқ» дегенді естіді.","en":"People often told him he was doing “the wrong thing”. He didn''t win every contest, got rejections, and at meetings with officials heard “aqsha zhoq” — there''s no money."},"turningPoint":{"ru":"Он понял, что легенды можно связать с экологией, а бумажные книги ограничены тиражом — так появилась идея сделать бота.","kk":"Ол аңыздарды экологиямен байланыстыруға болатынын, ал қағаз кітаптардың таралымы шектеулі екенін түсінді — осылай бот жасау идеясы пайда болды.","en":"He realised legends could be linked to ecology, and that paper books are limited by print runs — that''s how the idea of a bot came about."},"actions":{"ru":"Вместе с родителями напечатал 60–70 книг и продал их на ярмарках; часть выручки ушла на посадку 50 деревьев в Караганде. С командой — мама, эколог и разработчики — запустил телеграм-бот EcoPlaton со сказками, квестами и калькулятором углеродного следа.","kk":"Ата-анасымен бірге 60–70 кітап басып, оларды жәрмеңкелерде сатты; түскен ақшаның бір бөлігі Қарағандыда 50 ағаш отырғызуға жұмсалды. Командасымен — анасы, эколог және әзірлеушілер — ертегілері, квестері және көміртек ізінің калькуляторы бар EcoPlaton телеграм-ботын іске қосты.","en":"With his parents he printed 60–70 books and sold them at fairs; part of the money went to planting 50 trees in Karaganda. With a team — his mum, an ecologist and developers — he launched the EcoPlaton Telegram bot with tales, quests and a carbon-footprint calculator."},"now":{"ru":"На момент интервью он прошёл инкубацию в ИТ-хабе «Терриконовая долина», получил грант 500 тысяч тенге и готовил запуск экотропы с ботом в Боровом.","kk":"Сұхбат кезінде ол «Терриконовая долина» IT-хабында инкубациядан өтіп, 500 мың теңге грант алған және Бурабайда ботпен жұмыс істейтін экосоқпақты іске қосуға дайындалып жүрген.","en":"At the time of the interview he had completed incubation at the Terrikonovaya Dolina IT hub, won a 500,000-tenge grant and was preparing an eco-trail with the bot in Borovoe."},"advice":{"ru":"Главное — верить в себя и не сдаваться после отказов: доказывать не другим, а самому себе.","kk":"Ең бастысы — өзіңе сену және бас тартулардан кейін берілмеу: өзгелерге емес, өзіңе дәлелдеу.","en":"The main thing is to believe in yourself and not give up after rejections — prove it to yourself, not to others."}}'::jsonb, '{"start":[],"interests":["nature","creative","tech","business"],"fears":["judgement"],"education":["school"],"challenges":["money"],"motives":["impact","curiosity"],"decisions":["side-project"],"transitions":[]}'::jsonb, '[]'::jsonb)
insert into public.experiments (id, direction, difficulty, content) values
  ('exp-diplomacy-memo', 'diplomacy', 'medium', '{"title":{"ru":"Мини-записка по международному вопросу","kk":"Халықаралық мәселе бойынша шағын жазба","en":"One-page brief on an international issue"},"steps":{"ru":["Выбери один текущий международный вопрос, который тебе интересен.","Прочитай два источника из разных стран или с разными позициями и выпиши аргументы каждой стороны.","Напиши записку на одну страницу: суть вопроса, позиции сторон, возможные компромиссы.","Объясни её другу за три минуты и спроси, что осталось непонятным."],"kk":["Өзіңе қызықты бір өзекті халықаралық мәселені таңда.","Әртүрлі елдерден немесе әртүрлі позициядағы екі дереккөзді оқып, әр тараптың дәлелдерін жаз.","Бір беттік жазба жаз: мәселенің мәні, тараптардың позициялары, мүмкін келісімдер.","Оны досыңа үш минутта түсіндіріп, не түсініксіз қалғанын сұра."],"en":["Pick one current international issue that interests you.","Read two sources from different countries or with different positions and note each side''s arguments.","Write a one-page brief: the issue, each side''s position, possible compromises.","Explain it to a friend in three minutes and ask what remained unclear."]},"timeEstimate":{"ru":"3–4 ч","kk":"3–4 сағ","en":"3–4 h"},"resources":{"ru":["Сайт un.org (раздел новостей)","Новости двух разных изданий по одной теме"],"kk":["un.org сайты (жаңалықтар бөлімі)","Бір тақырып бойынша екі түрлі басылымның жаңалықтары"],"en":["The un.org website (news section)","News from two different outlets on the same topic"]},"outcome":{"ru":"Записка на одну страницу и опыт объяснения сложной темы простыми словами.","kk":"Бір беттік жазба және күрделі тақырыпты қарапайым сөзбен түсіндіру тәжірибесі.","en":"A one-page brief and practice explaining a complex topic in plain words."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли интересно понимать позицию противоположной стороны?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Қарсы тараптың позициясын түсіну қызықты болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Was it interesting to understand the opposite side''s position?"]}}'::jsonb),
  ('exp-entrepreneurship-test', 'entrepreneurship', 'hard', '{"title":{"ru":"Проверь идею на пяти людях","kk":"Идеяңды бес адамда тексер","en":"Test an idea on five people"},"steps":{"ru":["Сформулируй одну проблему, которую можно решить небольшим продуктом или услугой.","Поговори минимум с пятью людьми, у которых эта проблема есть: как они решают её сейчас?","Предложи одному человеку простейшее решение за небольшую плату или в обмен на отзыв.","Запиши, что узнал о клиентах и о себе в роли продавца."],"kk":["Шағын өніммен немесе қызметпен шешуге болатын бір мәселені тұжырымда.","Осы мәселесі бар кемінде бес адаммен сөйлес: олар қазір оны қалай шешеді?","Бір адамға ең қарапайым шешімді аз ақыға немесе пікір үшін ұсын.","Клиенттер және сатушы ретінде өзің туралы не білгеніңді жаз."],"en":["State one problem that a small product or service could solve.","Talk to at least five people who have this problem: how do they solve it today?","Offer one person the simplest solution for a small fee or in exchange for feedback.","Write down what you learned about customers and about yourself as a seller."]},"timeEstimate":{"ru":"6–8 ч за неделю","kk":"Апта ішінде 6–8 сағ","en":"6–8 h over a week"},"resources":{"ru":["Google Forms или обычный блокнот для заметок","Один знакомый, который сам что-то продавал"],"kk":["Google Forms немесе қарапайым жазба дәптері","Өзі бір нәрсе сатып көрген бір таныс"],"en":["Google Forms or a plain notebook for notes","One acquaintance who has sold something"]},"outcome":{"ru":"Проверенная или опровергнутая гипотеза и первое впечатление от общения с клиентами.","kk":"Расталған немесе жоққа шығарылған болжам және клиенттермен сөйлесудің алғашқы әсері.","en":"A confirmed or rejected hypothesis and a first feel for talking to customers."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли комфортно предлагать и слышать «нет»?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Ұсыну және «жоқ» деген жауап есту ыңғайлы болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Was it comfortable to offer something and hear no?"]}}'::jsonb),
  ('exp-psychology-diary', 'psychology', 'easy', '{"title":{"ru":"Неделя наблюдений за своими привычками","kk":"Өз әдеттерің бойынша бір апталық бақылау","en":"A week of observing your own habits"},"steps":{"ru":["Выбери одну привычку, например сон, телефон или откладывание дел.","Семь дней записывай по пять строк: что произошло, что ты почувствовал, что сделал.","Найди и прочитай одну популярную статью по теме и сравни с тем, что заметил.","Сделай три вывода и отметь, что в них факт, а что догадка."],"kk":["Бір әдетті таңда, мысалы ұйқы, телефон немесе істерді кейінге қалдыру.","Жеті күн бойы бес жолдан жаз: не болды, не сездің, не істедің.","Тақырып бойынша бір танымал мақаланы тауып оқы және өз байқағандарыңмен салыстыр.","Үш қорытынды жаса және олардың қайсысы факт, қайсысы болжам екенін белгіле."],"en":["Pick one habit, for example sleep, phone use or procrastination.","For seven days write five lines: what happened, what you felt, what you did.","Find and read one popular article on the topic and compare it with what you noticed.","Write three conclusions and mark which are facts and which are guesses."]},"timeEstimate":{"ru":"10–15 мин в день, 7 дней","kk":"Күніне 10–15 мин, 7 күн","en":"10–15 min a day for 7 days"},"resources":{"ru":["Блокнот или заметки в телефоне","Одна статья с понятным списком источников"],"kk":["Дәптер немесе телефондағы жазбалар","Дереккөздер тізімі нақты бір мақала"],"en":["A notebook or phone notes","One article with a clear list of sources"]},"outcome":{"ru":"Дневник наблюдений и практика отличать факты от догадок.","kk":"Бақылау күнделігі және фактіні болжамнан ажырату тәжірибесі.","en":"An observation log and practice separating facts from guesses."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли интересно разбираться в причинах поведения, а не только замечать его?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Мінез-құлықты тек байқау емес, оның себептерін түсіну қызықты болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you enjoy digging into the causes of behaviour rather than just noticing it?"]}}'::jsonb),
  ('exp-programming-first', 'programming', 'easy', '{"title":{"ru":"Первая маленькая программа","kk":"Алғашқы шағын бағдарлама","en":"Your first small program"},"steps":{"ru":["Пройди первое занятие курса CS50x или любого вводного курса по программированию.","Придумай крошечную задачу из жизни, например счётчик расходов или шуточный тест.","Напиши программу, которая её решает, даже если она получится неидеальной.","Покажи результат другу и запиши, на каких местах застрял."],"kk":["CS50x курсының алғашқы сабағын немесе кез келген кіріспе бағдарламалау курсын өт.","Өмірден өте кішкентай тапсырма ойлап тап, мысалы шығын санағышы немесе әзіл тест.","Оны шешетін бағдарлама жаз, ол кемелсіз болса да.","Нәтижені досыңа көрсетіп, қай жерлерде тұрып қалғаныңды жаз."],"en":["Complete the first lesson of CS50x or any introductory programming course.","Come up with a tiny real-life task, such as an expense counter or a fun quiz.","Write a program that solves it, even if it is imperfect.","Show the result to a friend and write down where you got stuck."]},"timeEstimate":{"ru":"2–3 ч","kk":"2–3 сағ","en":"2–3 h"},"resources":{"ru":["cs50.harvard.edu/x (бесплатный курс)","Любой бесплатный онлайн-редактор кода"],"kk":["cs50.harvard.edu/x (тегін курс)","Кез келген тегін онлайн код редакторы"],"en":["cs50.harvard.edu/x (free course)","Any free online code editor"]},"outcome":{"ru":"Работающая маленькая программа и понимание, как ощущается процесс программирования.","kk":"Жұмыс істейтін шағын бағдарлама және бағдарламалау процесінің қандай екенін түсіну.","en":"A working small program and a sense of what programming feels like."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе искать ошибки и разбираться, почему не работает?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Қателерді іздеу және неге жұмыс істемейтінін түсіну ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like hunting for errors and figuring out why something does not work?"]}}'::jsonb),
  ('exp-design-redo', 'design', 'easy', '{"title":{"ru":"Переделай один неудобный экран","kk":"Бір ыңғайсыз экранды қайта жаса","en":"Redesign one awkward screen"},"steps":{"ru":["Выбери экран приложения или сайта, которым неудобно пользоваться, и запиши три проблемы.","Нарисуй на бумаге свой вариант решения.","Перерисуй его в бесплатном редакторе, например Figma или Canva.","Покажи двум людям и спроси, что им понятно, а что нет."],"kk":["Пайдалануға ыңғайсыз қосымша немесе сайт экранын таңда да, үш мәселесін жаз.","Шешімнің өз нұсқасын қағазға сыз.","Оны тегін редакторда қайта сыз, мысалы Figma немесе Canva.","Екі адамға көрсетіп, нені түсінетінін, нені түсінбейтінін сұра."],"en":["Pick an app or website screen that is awkward to use and write down three problems.","Sketch your own solution on paper.","Redraw it in a free editor such as Figma or Canva.","Show it to two people and ask what is clear and what is not."]},"timeEstimate":{"ru":"2–3 ч","kk":"2–3 сағ","en":"2–3 h"},"resources":{"ru":["figma.com (бесплатный тариф)","canva.com"],"kk":["figma.com (тегін тариф)","canva.com"],"en":["figma.com (free plan)","canva.com"]},"outcome":{"ru":"Эскиз и редизайн экрана с отзывами от двух людей.","kk":"Эскиз және екі адамның пікірі бар экранның қайта дизайны.","en":"A sketch and a redesigned screen with feedback from two people."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе принимать критику и менять работу по отзывам?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Сынды қабылдап, жұмысты пікірге қарай өзгерту ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like taking critique and changing the work in response?"]}}'::jsonb),
  ('exp-education-mini-lesson', 'education', 'easy', '{"title":{"ru":"Проведи мини-урок","kk":"Шағын сабақ өткіз","en":"Teach a mini lesson"},"steps":{"ru":["Выбери навык, которым владеешь, и сформулируй цель урока одним предложением.","Подготовь план на 15–20 минут с одним примером и одним упражнением.","Проведи урок для друга, младшего брата или сестры.","Спроси, что было понятно, а что нет, и запиши, что бы изменил."],"kk":["Өзің білетін дағдыны таңда және сабақтың мақсатын бір сөйлеммен тұжырымда.","Бір мысалы және бір жаттығуы бар 15–20 минуттық жоспар дайында.","Сабақты досыңа, інісіне немесе қарындасыңа өткіз.","Не түсінікті, не түсініксіз болғанын сұрап, нені өзгертетініңді жаз."],"en":["Choose a skill you have and state the goal of the lesson in one sentence.","Prepare a 15–20 minute plan with one example and one exercise.","Teach it to a friend or a younger sibling.","Ask what was clear and what was not, and note what you would change."]},"timeEstimate":{"ru":"2 ч","kk":"2 сағ","en":"2 h"},"resources":{"ru":["Лист бумаги или доска","Один готовый ученик, который согласен быть тестовым"],"kk":["Қағаз парағы немесе тақта","Сынақ оқушысы болуға келісетін бір адам"],"en":["A sheet of paper or a whiteboard","One willing learner to test on"]},"outcome":{"ru":"План мини-урока и первый опыт объяснения другому человеку.","kk":"Шағын сабақ жоспары және басқа адамға түсіндірудің алғашқы тәжірибесі.","en":"A mini-lesson plan and a first experience of explaining to someone."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Радовало ли тебя, когда другой человек наконец понимал?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Басқа адам ақыры түсінгенде қуандың ба?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did it feel good when the other person finally understood?"]}}'::jsonb),
  ('exp-media-interview', 'media', 'medium', '{"title":{"ru":"Короткое интервью и материал","kk":"Қысқа сұхбат және материал","en":"A short interview and a piece"},"steps":{"ru":["Выбери человека, чья работа тебе интересна, и подготовь пять вопросов.","Проведи интервью на 15 минут, записав его с разрешения собеседника.","Напиши текст на 300 слов или смонтируй видео на две минуты.","Покажи результат собеседнику, чтобы проверить факты, и одному читателю."],"kk":["Жұмысы саған қызық адамды таңда және бес сұрақ дайында.","Әңгімелесушінің рұқсатымен жазып, 15 минуттық сұхбат жүргіз.","300 сөздік мәтін жаз немесе екі минуттық бейне монтажда.","Фактілерді тексеру үшін нәтижені әңгімелесушіге және бір оқырманға көрсет."],"en":["Choose a person whose work interests you and prepare five questions.","Interview them for 15 minutes, recording with their permission.","Write a 300-word text or edit a two-minute video.","Show the result to your interviewee to check facts, and to one reader."]},"timeEstimate":{"ru":"3–4 ч","kk":"3–4 сағ","en":"3–4 h"},"resources":{"ru":["Диктофон в телефоне","Любой бесплатный видеоредактор"],"kk":["Телефондағы диктофон","Кез келген тегін бейне редактор"],"en":["The voice recorder on your phone","Any free video editor"]},"outcome":{"ru":"Готовый короткий материал и понимание, как устроена работа с источниками.","kk":"Дайын қысқа материал және дереккөздермен жұмыс қалай ұйымдастырылатынын түсіну.","en":"A finished short piece and an idea of how working with sources goes."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе слушать людей и превращать услышанное в текст?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Адамдарды тыңдап, естігеніңді мәтінге айналдыру ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like listening to people and turning it into a text?"]}}'::jsonb),
  ('exp-research-mini-survey', 'research', 'medium', '{"title":{"ru":"Мини-исследование на десяти людях","kk":"Он адамға арналған шағын зерттеу","en":"A mini study with ten people"},"steps":{"ru":["Сформулируй один вопрос, на который хочется найти ответ, например про привычки студентов.","Составь анкету из пяти вопросов в Google Forms.","Собери минимум десять ответов и посчитай простые итоги.","Напиши полстраницы выводов и отдельно отметь, чего выборка из десяти человек не доказывает."],"kk":["Жауабын табуды қалайтын бір сұрақты тұжырымда, мысалы студенттердің әдеттері туралы.","Google Forms-та бес сұрақтан тұратын сауалнама жаса.","Кемінде он жауап жинап, қарапайым қорытындыларды есепте.","Жарты бет қорытынды жаз да, он адамдық таңдау нені дәлелдемейтінін бөлек белгіле."],"en":["State one question you want answered, for example about student habits.","Make a five-question survey in Google Forms.","Collect at least ten answers and calculate simple results.","Write half a page of findings and note separately what a sample of ten does not prove."]},"timeEstimate":{"ru":"3–5 ч","kk":"3–5 сағ","en":"3–5 h"},"resources":{"ru":["Google Forms","Таблица для подсчёта ответов"],"kk":["Google Forms","Жауаптарды есептеуге арналған кесте"],"en":["Google Forms","A spreadsheet for counting answers"]},"outcome":{"ru":"Мини-отчёт и понимание, насколько осторожно нужно делать выводы.","kk":"Шағын есеп және қорытындыны қаншалықты сақтықпен жасау керектігін түсіну.","en":"A mini report and a sense of how careful conclusions must be."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли интересно искать ответ там, где его нет в готовом виде?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Жауабы дайын жоқ жерден оны іздеу қызықты болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Was it interesting to look for an answer that does not exist ready-made?"]}}'::jsonb),
  ('exp-social-impact-shift', 'social-impact', 'easy', '{"title":{"ru":"Одна смена волонтёрства","kk":"Бір ауысым еріктілік","en":"One volunteering shift"},"steps":{"ru":["Найди местную организацию или инициативу, которой нужны волонтёры, и напиши ей.","Приди на одну смену и выполни то, о чём попросят.","Спроси координатора, какие навыки здесь нужнее всего и как он сам сюда пришёл.","Запиши, что было неожиданного и какой эффект ты увидел сам."],"kk":["Еріктілер қажет жергілікті ұйымды немесе бастаманы тауып, оған жаз.","Бір ауысымға келіп, сұраған істі орында.","Үйлестірушіден мұнда қандай дағдылар көбірек қажет екенін және өзі мұнда қалай келгенін сұра.","Не күтпеген болғанын және өзің қандай әсер көргеніңді жаз."],"en":["Find a local organisation or initiative that needs volunteers and write to them.","Come to one shift and do what they ask.","Ask the coordinator which skills matter most here and how they got started.","Write down what was unexpected and what effect you saw yourself."]},"timeEstimate":{"ru":"3–4 ч, не считая дороги","kk":"3–4 сағ, жолды қоспағанда","en":"3–4 h, not counting travel"},"resources":{"ru":["Страницы местных организаций в соцсетях","unv.org и другие платформы для волонтёров"],"kk":["Жергілікті ұйымдардың әлеуметтік желідегі беттері","unv.org және еріктілерге арналған басқа платформалар"],"en":["Social media pages of local organisations","unv.org and other volunteering platforms"]},"outcome":{"ru":"Первый опыт участия и список навыков, которые пригодились.","kk":"Қатысудың алғашқы тәжірибесі және пайдасы тиген дағдылар тізімі.","en":"A first taste of taking part and a list of skills that proved useful."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли приятно именно участие, а не то, как это выглядит со стороны?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Тек сырттан қалай көрінетіні емес, қатысудың өзі ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you enjoy the participation itself rather than how it looks from outside?"]}}'::jsonb),
  ('exp-medicine-conversation', 'medicine', 'medium', '{"title":{"ru":"Разговор с медицинским работником и курс первой помощи","kk":"Медицина қызметкерімен әңгіме және алғашқы көмек курсы","en":"A conversation with a health worker and a first-aid lesson"},"steps":{"ru":["Подготовь восемь вопросов о работе: что нравится, что тяжело, как выглядит обычный день.","Поговори 20 минут с медсестрой, врачом или фельдшером, которого знаешь или которого тебе порекомендуют.","Пройди короткий видеоурок или курс по основам первой помощи.","Запиши, что тебя привлекло, а что отпугнуло, и обсуди с кем-то из близких."],"kk":["Жұмыс туралы сегіз сұрақ дайында: не ұнайды, не қиын, қарапайым күн қалай өтеді.","Өзің танитын немесе саған ұсынылған мейірбикемен, дәрігермен немесе фельдшермен 20 минут сөйлес.","Алғашқы көмек негіздері бойынша қысқа бейнесабақ немесе курс өт.","Сені не тартқанын, не үркіткенін жазып, жақындарыңның біреуімен талқыла."],"en":["Prepare eight questions about the job: what they like, what is hard, what a normal day looks like.","Talk for 20 minutes with a nurse, doctor or paramedic you know or are introduced to.","Take a short video lesson or course on first-aid basics.","Write down what attracted you and what put you off, and discuss it with someone close."]},"timeEstimate":{"ru":"3–4 ч","kk":"3–4 сағ","en":"3–4 h"},"resources":{"ru":["Знакомые или родственники, работающие в медицине","Бесплатные видеоуроки по первой помощи"],"kk":["Медицинада жұмыс істейтін таныстар немесе туыстар","Алғашқы көмек бойынша тегін бейнесабақтар"],"en":["Acquaintances or relatives who work in healthcare","Free first-aid video lessons"]},"outcome":{"ru":"Более реалистичная картина повседневной работы в медицине.","kk":"Медицинадағы күнделікті жұмыстың нақтырақ көрінісі.","en":"A more realistic picture of everyday work in healthcare."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Привлекает ли тебя сама рутина работы с людьми в сложных ситуациях?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Қиын жағдайдағы адамдармен жұмыстың күнделікті жұмысы сені тарта ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Are you drawn to the daily routine of working with people in hard situations?"]}}'::jsonb),
  ('exp-law-plain-language', 'law', 'medium', '{"title":{"ru":"Разбор одного договора простым языком","kk":"Бір шартты қарапайым тілмен талдау","en":"Explain one contract in plain language"},"steps":{"ru":["Возьми обычный документ, например типовой договор аренды или пользовательское соглашение.","Отметь пункты, которые непонятны или кажутся рискованными.","Найди в официальных источниках, что говорит закон по двум-трём таким вопросам.","Перескажи документ простым языком на одной странице и покажи человеку, знающему право, если есть такая возможность."],"kk":["Қарапайым құжатты ал, мысалы жалдаудың үлгілік шартын немесе пайдаланушы келісімін.","Түсініксіз немесе қауіпті көрінетін тармақтарды белгіле.","Осындай екі-үш мәселе бойынша заң не дейтінін ресми дереккөздерден тап.","Құжатты қарапайым тілмен бір бетте қайта айтып, мүмкіндік болса, құқықты білетін адамға көрсет."],"en":["Take an everyday document, such as a standard rental agreement or terms of service.","Mark the clauses that are unclear or look risky.","Look up in official sources what the law says about two or three of these points.","Retell the document in plain language on one page and, if possible, show it to someone who knows the law."]},"timeEstimate":{"ru":"2–3 ч","kk":"2–3 сағ","en":"2–3 h"},"resources":{"ru":["Официальные базы законодательства твоей страны","Любой типовой договор из открытых источников"],"kk":["Еліңдегі заңнаманың ресми базалары","Ашық дереккөздердегі кез келген үлгілік шарт"],"en":["Official legislation databases in your country","Any template contract from open sources"]},"outcome":{"ru":"Страница с разбором документа и понимание, как читаются юридические тексты.","kk":"Құжат талдауы бар бет және заң мәтіндері қалай оқылатынын түсіну.","en":"A page analysing a document and a feel for how legal texts are read."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе внимательно читать мелкий текст и искать неточности?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Ұсақ мәтінді мұқият оқып, дәлсіздіктерді іздеу ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like reading fine print closely and looking for gaps?"]}}'::jsonb),
  ('exp-engineering-paper-bridge', 'engineering', 'easy', '{"title":{"ru":"Бумажный мост и испытание нагрузкой","kk":"Қағаз көпір және жүктемемен сынау","en":"A paper bridge and a load test"},"steps":{"ru":["Сделай мост пролётом около 20 см только из бумаги и скотча.","Постепенно клади на него монетки и запиши, сколько он выдержал.","Измени одну деталь, например форму или складки, и повтори испытание.","Сравни результаты и объясни, почему вторая версия работает лучше или хуже."],"kk":["Тек қағаз бен скотчтан шамамен 20 см аралықты көпір жаса.","Үстіне біртіндеп тиындар қойып, қанша көтергенін жаз.","Бір бөлшекті, мысалы пішінді немесе бүктемелерді өзгертіп, сынауды қайтала.","Нәтижелерді салыстырып, екінші нұсқаның неге жақсы немесе нашар жұмыс істейтінін түсіндір."],"en":["Build a bridge about 20 cm long from paper and tape only.","Gradually place coins on it and note how many it held.","Change one detail, such as the shape or folds, and test again.","Compare the results and explain why the second version works better or worse."]},"timeEstimate":{"ru":"2–3 ч","kk":"2–3 сағ","en":"2–3 h"},"resources":{"ru":["Бумага, скотч, монеты","Учебник физики за школьный курс"],"kk":["Қағаз, скотч, тиындар","Мектеп курсының физика оқулығы"],"en":["Paper, tape, coins","A school physics textbook"]},"outcome":{"ru":"Две версии конструкции, таблица результатов и объяснение разницы.","kk":"Құрылымның екі нұсқасы, нәтиже кестесі және айырмашылық түсіндірмесі.","en":"Two versions of a structure, a results table and an explanation of the difference."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе переделывать, измерять и снова проверять?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Қайта жасау, өлшеу және қайта тексеру ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like redoing, measuring and testing again?"]}}'::jsonb),
  ('exp-data-first-analysis', 'data-ml', 'medium', '{"title":{"ru":"Первый анализ данных","kk":"Деректердің алғашқы талдауы","en":"Your first data analysis"},"steps":{"ru":["Возьми небольшой набор данных: свой журнал сна или расходов либо открытый набор с kaggle.com/datasets.","Посчитай среднее, минимум и максимум и построй один график в таблице или Python.","Запиши три вывода и отметь, какие из них можно проверить дальше.","Если хочется больше, пройди первый урок курса «Intro to Machine Learning» на kaggle.com/learn."],"kk":["Шағын деректер жиынын ал: өз ұйқы немесе шығын журналыңды не kaggle.com/datasets сайтындағы ашық жиынды.","Орташа, ең кіші және ең үлкен мәнді есепте және кестеде немесе Python-да бір график сал.","Үш қорытынды жазып, олардың қайсысын әрі қарай тексеруге болатынын белгіле.","Көбірек қаласаң, kaggle.com/learn сайтындағы «Intro to Machine Learning» курсының алғашқы сабағын өт."],"en":["Take a small dataset: your own sleep or spending log, or an open one from kaggle.com/datasets.","Calculate the average, minimum and maximum and make one chart in a spreadsheet or Python.","Write three conclusions and mark which ones can be tested further.","If you want more, take the first lesson of the Intro to Machine Learning course at kaggle.com/learn."]},"timeEstimate":{"ru":"3–4 ч","kk":"3–4 сағ","en":"3–4 h"},"resources":{"ru":["kaggle.com/datasets и kaggle.com/learn","Google Sheets или любая электронная таблица"],"kk":["kaggle.com/datasets және kaggle.com/learn","Google Sheets немесе кез келген электрондық кесте"],"en":["kaggle.com/datasets and kaggle.com/learn","Google Sheets or any spreadsheet"]},"outcome":{"ru":"Один график, три вывода и первое ощущение от работы с данными.","kk":"Бір график, үш қорытынды және деректермен жұмыстың алғашқы сезімі.","en":"One chart, three conclusions and a first feel for working with data."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Было ли интересно искать закономерности даже тогда, когда ответ получался скучным?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Жауап жалықтырарлық болса да, заңдылықтарды іздеу қызықты болды ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Was it interesting to look for patterns even when the answer was dull?"]}}'::jsonb),
  ('exp-environment-audit', 'environment', 'easy', '{"title":{"ru":"Экоаудит одного места","kk":"Бір жердің экологиялық аудиті","en":"An eco-audit of one place"},"steps":{"ru":["Выбери одно место: свой двор, класс или кухню.","Неделю записывай, сколько и какого мусора там появляется, и снимай фото.","Предложи три конкретных изменения и оцени, что из этого реально выполнить.","Расскажи свой план тем, кто пользуется этим местом, и попробуй одно изменение."],"kk":["Бір жерді таңда: өз аулаңды, сыныбыңды немесе асүйіңді.","Бір апта бойы онда қандай және қанша қоқыс пайда болатынын жазып, фотоға түсір.","Үш нақты өзгеріс ұсынып, олардың қайсысын нақты орындауға болатынын бағала.","Жоспарыңды сол жерді пайдаланатындарға айтып, бір өзгерісті байқап көр."],"en":["Choose one place: your yard, classroom or kitchen.","For a week, note how much and what kind of waste appears there and take photos.","Propose three concrete changes and judge which are realistic.","Present the plan to the people who use the place and try one change."]},"timeEstimate":{"ru":"10 мин в день, 7 дней, плюс 1 ч","kk":"Күніне 10 мин, 7 күн, қосымша 1 сағ","en":"10 min a day for 7 days, plus 1 h"},"resources":{"ru":["Блокнот и камера телефона","Местные правила раздельного сбора отходов"],"kk":["Дәптер және телефон камерасы","Қалдықтарды бөлек жинаудың жергілікті ережелері"],"en":["A notebook and your phone camera","Local rules on waste sorting"]},"outcome":{"ru":"Короткий план улучшений и опыт убеждать людей, а не только замечать проблему.","kk":"Жақсартулардың қысқа жоспары және мәселені тек байқау емес, адамдарды сендіру тәжірибесі.","en":"A short improvement plan and practice persuading people, not just spotting a problem."},"reflection":{"ru":["Тебе понравился сам процесс или только идея этим заниматься?","Что тебя удивило?","Что было скучным, трудным или неприятным?","Хочется ли сделать следующий шаг? Какой именно?","Нравилось ли тебе превращать наблюдения в конкретные действия?"],"kk":["Саған процестің өзі ұнады ма, әлде тек осымен айналысу идеясы ма?","Сені не таңқалдырды?","Не жалықтырарлық, қиын немесе жағымсыз болды?","Келесі қадамды жасағың келе ме? Нақты қандайын?","Бақылауларды нақты әрекетке айналдыру ұнады ма?"],"en":["Did you enjoy the process itself, or only the idea of doing it?","What surprised you?","What felt boring, hard or unpleasant?","Do you want to take a next step? Which one exactly?","Did you like turning observations into concrete actions?"]}}'::jsonb)
insert into public.opportunities (id, name, kind, levels, country, cost, description, eligibility, url, deadline, verified_at, status) values
  ('bolashak', 'Bolashak (Болашак)', 'scholarship', '{master,phd}'::text[], 'international', 'unknown', '{"ru":"Международная стипендия правительства Казахстана для обучения и научных стажировок за рубежом. Программу ведёт Центр международных программ.","kk":"Қазақстан Үкіметінің шетелде оқуға және ғылыми тағылымдамадан өтуге арналған халықаралық стипендиясы. Бағдарламаны Халықаралық бағдарламалар орталығы жүргізеді.","en":"An international scholarship of the Government of Kazakhstan for study and research internships abroad, run by the Center for International Programs."}'::jsonb, '{"ru":"Только для граждан Казахстана. Для магистратуры нужно безусловное приглашение из вуза рекомендуемого списка и сертификат по казахскому языку не ниже B1. Точные правила — на официальном сайте.","kk":"Тек Қазақстан азаматтарына. Магистратура үшін ұсынылған тізімдегі университеттен шартсыз шақыру және қазақ тілінен кемінде B1 сертификаты қажет. Нақты ережелер — ресми сайтта.","en":"Kazakhstan citizens only. For a master’s you need an unconditional offer from a university on the recommended list and a Kazakh language certificate of at least B1. Exact rules are on the official site."}'::jsonb, 'https://bolashak.gov.kz', null::date, '2026-11-18'::date, 'verified'),
  ('erasmus-plus', 'Erasmus+', 'exchange', '{bachelor,master,phd}'::text[], 'europe', 'unknown', '{"ru":"Программа Европейского союза в сфере образования, обучения, молодёжи и спорта. Включает обмены студентов, стажировки и совместные магистерские программы.","kk":"Еуропалық Одақтың білім беру, оқыту, жастар және спорт саласындағы бағдарламасы. Студенттер алмасуын, тағылымдамаларды және бірлескен магистратура бағдарламаларын қамтиды.","en":"The European Union programme for education, training, youth and sport. It includes student exchanges, traineeships and joint master''s programmes."}'::jsonb, '{"ru":"Возможности для жителей стран-партнёров, включая Казахстан, зависят от конкретного направления. Условия и сроки уточняйте на официальном сайте.","kk":"Әріптес елдердің, соның ішінде Қазақстанның тұрғындарына қолжетімділік нақты бағытқа байланысты. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Access for residents of partner countries, including Kazakhstan, depends on the specific action. Check conditions and deadlines on the official website."}'::jsonb, 'https://erasmus-plus.ec.europa.eu', null::date, '2026-11-18'::date, 'verified'),
  ('daad', 'DAAD', 'scholarship', '{master,phd}'::text[], 'germany', 'unknown', '{"ru":"Немецкая служба академических обменов: стипендии, а также портал Study Guide Germany для иностранных студентов.","kk":"Неміс академиялық алмасу қызметі: стипендиялар және шетелдік студенттерге арналған Study Guide Germany порталы.","en":"The German Academic Exchange Service: scholarships plus the Study Guide Germany platform for international students."}'::jsonb, '{"ru":"Набор стипендий большой, у каждой свои условия. Условия и сроки уточняйте на официальном сайте.","kk":"Стипендиялар көп, әрқайсысының өз шарттары бар. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"There are many scholarships, each with its own conditions. Check conditions and deadlines on the official website."}'::jsonb, 'https://www.daad.de/en/', null::date, '2026-11-18'::date, 'verified'),
  ('chevening', 'Chevening', 'scholarship', '{master}'::text[], 'uk', 'unknown', '{"ru":"Стипендия правительства Великобритании для одногодичной магистратуры в британских университетах.","kk":"Ұлыбритания Үкіметінің Британ университеттерінде бір жылдық магистратурада оқуға арналған стипендиясы.","en":"A UK government scholarship for a one-year master''s degree at a UK university."}'::jsonb, '{"ru":"Казахстан участвует в программе. Набор на 2027–2028 уже закрыт, следите за открытием следующего на официальном сайте.","kk":"Қазақстан бағдарламаға қатысады. 2027–2028 жылдарға қабылдау жабылды, келесісінің ашылуын ресми сайттан бақылаңыз.","en":"Kazakhstan takes part. Applications for 2027–2028 are closed; watch the official site for the next round."}'::jsonb, 'https://www.chevening.org', null::date, '2026-11-18'::date, 'verified'),
  ('fulbright-foreign-student', 'Fulbright Foreign Student Program', 'scholarship', '{master,phd}'::text[], 'usa', 'unknown', '{"ru":"Программа правительства США, которая позволяет гражданам других стран учиться в США. Заявка подаётся через Фулбрайтовскую комиссию, фонд или посольство США в своей стране.","kk":"АҚШ Үкіметінің басқа ел азаматтарына АҚШ-та оқуға мүмкіндік беретін бағдарламасы. Өтінім өз еліңдегі Фулбрайт комиссиясы, қор немесе АҚШ елшілігі арқылы беріледі.","en":"A US government programme that lets citizens of other countries study in the United States. Applications go through the Fulbright Commission, foundation or US Embassy in your home country."}'::jsonb, '{"ru":"Условия и сроки уточняйте на официальном сайте.","kk":"Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Check conditions and deadlines on the official website."}'::jsonb, 'https://foreign.fulbrightonline.org', null::date, '2026-11-18'::date, 'verified'),
  ('stipendium-hungaricum', 'Stipendium Hungaricum', 'scholarship', '{bachelor,master,phd}'::text[], 'hungary', 'unknown', '{"ru":"Государственная стипендия Венгрии для иностранных студентов в венгерских университетах.","kk":"Венгрия Үкіметінің шетелдік студенттерге арналған, Венгрия университеттерінде оқуға берілетін стипендиясы.","en":"A Hungarian government scholarship for international students at Hungarian universities."}'::jsonb, '{"ru":"Приём на 2026/27 учебный год закрыт. Сроки следующего набора смотрите на официальном сайте.","kk":"2026/27 оқу жылына қабылдау жабық. Келесі қабылдау мерзімін ресми сайттан қараңыз.","en":"Applications for 2026/27 are closed. Check the official site for the next round."}'::jsonb, 'https://stipendiumhungaricum.hu', null::date, '2026-11-18'::date, 'verified'),
  ('turkiye-burslari', 'Türkiye Bursları', 'scholarship', '{bachelor,master,phd}'::text[], 'turkey', 'unknown', '{"ru":"Стипендия Турции для иностранных студентов: бакалавриат, магистратура, докторантура и исследовательские программы. Кроме финансовой поддержки, программа помогает с местом в университете.","kk":"Шетелдік студенттерге арналған Түркия стипендиясы: бакалавриат, магистратура, докторантура және зерттеу бағдарламалары. Қаржылай қолдаудан бөлек, бағдарлама университеттен орын алуға көмектеседі.","en":"Türkiye’s scholarship for international students: bachelor’s, master’s, PhD and research programmes. Besides financial support, it also arranges the university placement."}'::jsonb, '{"ru":"Для иностранных граждан. Условия и сроки уточняйте на официальном сайте.","kk":"Шетел азаматтарына арналған. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"For international citizens. Check conditions and deadlines on the official website."}'::jsonb, 'https://turkiyeburslari.gov.tr', null::date, '2026-11-18'::date, 'verified'),
  ('european-solidarity-corps', 'European Solidarity Corps', 'volunteering', '{any}'::text[], 'europe', 'unknown', '{"ru":"Волонтёрские и общественные проекты в Европе для молодых людей 18–30 лет на портале Европейского союза для молодёжи.","kk":"Еуропалық Одақтың жастар порталындағы 18–30 жас аралығындағы жастарға арналған Еуропадағы еріктілік және қоғамдық жобалар.","en":"Volunteering and community projects in Europe for young people aged 18 to 30 on the European Youth Portal."}'::jsonb, '{"ru":"Участие зависит от проекта и страны проживания. Условия и сроки уточняйте на официальном сайте.","kk":"Қатысу жобаға және тұрғылықты елге байланысты. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Participation depends on the project and your country of residence. Check conditions and deadlines on the official website."}'::jsonb, 'https://youth.europa.eu/solidarity_en', null::date, '2026-11-18'::date, 'verified'),
  ('un-volunteers', 'UN Volunteers (UNV)', 'volunteering', '{any}'::text[], 'international', 'unknown', '{"ru":"Онлайн-волонтёрство Программы добровольцев ООН: задания от организаций со всего мира, которые можно выполнять из дома. Без оплаты, до 20 часов в неделю и до 12 недель.","kk":"БҰҰ еріктілер бағдарламасының онлайн еріктілігі: әлемнің түкпір-түкпіріндегі ұйымдардың үйден орындауға болатын тапсырмалары. Ақысыз, аптасына 20 сағатқа дейін және 12 аптаға дейін.","en":"Online volunteering with the UN Volunteers programme: tasks from organisations around the world that you can do from home. Unpaid, up to 20 hours a week for up to 12 weeks."}'::jsonb, '{"ru":"С 18 лет, особый опыт не нужен; требования к каждому заданию ставит организация. Регистрация на платформе UVP. Подробности — на официальном сайте.","kk":"18 жастан бастап, арнайы тәжірибе қажет емес; әр тапсырмаға талапты ұйым қояды. UVP платформасында тіркелу. Толығырақ — ресми сайтта.","en":"From 18, no special background needed; each assignment has its own requirements set by the host. Sign up on the UVP platform. Details are on the official site."}'::jsonb, 'https://www.unv.org/become-online-volunteer', null::date, '2026-11-18'::date, 'verified'),
  ('coursera', 'Coursera', 'course', '{any}'::text[], 'online', 'mixed', '{"ru":"Платформа онлайн-курсов от университетов и компаний. На сайте можно посмотреть первый модуль многих курсов бесплатно, а также подать заявку на финансовую помощь.","kk":"Университеттер мен компаниялардың онлайн-курстар платформасы. Сайтта көптеген курстардың бірінші модулін тегін көруге және қаржылық көмекке өтінім беруге болады.","en":"An online learning platform with courses from universities and companies. You can preview the first module of many courses for free and apply for financial aid."}'::jsonb, '{"ru":"Открыто для всех. Что бесплатно, а что нет, зависит от курса. Условия и сроки уточняйте на официальном сайте.","kk":"Барлығына ашық. Не тегін, не ақылы екені курсқа байланысты. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Open to everyone. What is free depends on the course. Check conditions and deadlines on the official website."}'::jsonb, 'https://www.coursera.org', null::date, '2026-11-18'::date, 'verified'),
  ('edx', 'edX', 'course', '{any}'::text[], 'online', 'mixed', '{"ru":"Платформа онлайн-курсов от университетов, в том числе с форматом прослушивания курса (audit).","kk":"Университеттердің онлайн-курстар платформасы, оның ішінде курсты тыңдау (audit) форматы бар.","en":"An online learning platform with university courses, including an audit option for many of them."}'::jsonb, '{"ru":"Открыто для всех. Условия аудита зависят от курса. Условия и сроки уточняйте на официальном сайте.","kk":"Барлығына ашық. Аудит шарттары курсқа байланысты. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"Open to everyone. Audit conditions depend on the course. Check conditions and deadlines on the official website."}'::jsonb, 'https://www.edx.org', null::date, '2026-11-18'::date, 'verified'),
  ('cs50x', 'CS50x (Harvard)', 'course', '{any}'::text[], 'online', 'free', '{"ru":"Вводный курс Гарварда по информатике и программированию. Его можно проходить бесплатно, платные только сертификаты и кредиты.","kk":"Гарвардтың информатика және бағдарламалау бойынша кіріспе курсы. Оны тегін өтуге болады, тек сертификаттар мен кредиттер ақылы.","en":"Harvard''s introductory computer science and programming course. It is free to take; only certificates and credit are paid."}'::jsonb, '{"ru":"Предварительные знания не нужны. Условия и сроки уточняйте на официальном сайте.","kk":"Алдын ала білім қажет емес. Шарттар мен мерзімдерін ресми сайттан нақтылаңыз.","en":"No prior knowledge needed. Check conditions and deadlines on the official website."}'::jsonb, 'https://cs50.harvard.edu/x', null::date, '2026-11-18'::date, 'verified')
